<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { UploadFilled, QuestionFilled } from '@element-plus/icons-vue';
import { ElMessage } from 'element-plus';
import request, { apiRequest } from '../api/request';

interface Plan{historyRetentionDays:number;historyRetentionMonths:number;id:string;code:string;name:string;description?:string;deviceLimit:number;pointLimit:number;scadaProjectLimit:number;userLimit:number;monthlyPriceCents:number;priceCents:number;billingCycles:Array<'MONTHLY'|'YEARLY'>;quoteOnly:boolean;enabled:boolean;sortOrder:number;currency:string}
interface Addon{pricePending:boolean;id:string;name:string;description?:string;resourceType:string;quantity:number;priceCents:number;quoteOnly:boolean}
interface Order{id:string;orderNo:string;orderType:string;targetPlan?:Plan;addon?:Addon;addonQuantity:number;amountCents:number;paymentAmountCents?:number;paymentMethod?:'MANUAL'|'ALIPAY';paymentStatus?:string;status:string;requestedAt:string;financeReviews?:Array<{note?:string;reviewerName:string;createdAt:string}>}
interface Summary{historyRetention?:{label:string;queryEarliestAt:string;graceEndsAt?:string;addonExpiresAt?:string;addonMonths:number};plan?:Plan;subscription?:{status:string;billingCycle:string;startedAt:string;expiresAt:string;graceEndsAt:string};usage:Record<string,{used:number;limit:number}>;pendingOrder?:Order;notifications:Array<{id:string;title:string;message:string;readAt?:string;createdAt:string}>;entitlementChanges:Array<{id:string;changeType:string;description?:string;createdAt:string}>}
interface Checkout{gateway:string;method:'POST';fields:Record<string,string>;sandbox:boolean;paymentAmountCents:number}
const route=useRoute(),router=useRouter();
const plans=ref<Plan[]>([]),addons=ref<Addon[]>([]),summary=ref<Summary>(),history=ref<Order[]>([]),loading=ref(false),dialogVisible=ref(false),targetPlan=ref<Plan>(),targetAddon=ref<Addon>(),orderType=ref<'UPGRADE'|'RENEW'|'EXPANSION'>('UPGRADE'),billingCycle=ref<'MONTHLY'|'YEARLY'>('YEARLY'),addonQuantity=ref(1),voucher=ref<File>(),paymentReference=ref(''),paidBy=ref(''),paymentMethod=ref<'ALIPAY'|'MANUAL'>('ALIPAY'),submitting=ref(false),checkingPayment=ref(false);
const availablePlans=computed(()=>plans.value.filter(p=>p.enabled&&p.id!==summary.value?.plan?.id&&p.sortOrder>(summary.value?.plan?.sortOrder??-1)));
const money=(v:number)=>`¥${(v/100).toLocaleString('zh-CN',{minimumFractionDigits:2})}`;
const quota=(v:number)=>v===0?'不限':v.toLocaleString();
const statusText:Record<string,string>={PENDING_PAYMENT:'待支付',PENDING_REVIEW:'财务审核中',APPROVED:'已完成',REJECTED:'已驳回',PAYMENT_CLOSED:'支付已关闭',PAYMENT_FAILED:'支付失败'};
const subStatus:Record<string,string>={ACTIVE:'生效中',GRACE:'宽限期',EXPIRED:'已到期',SUSPENDED:'已暂停'};
const typeText:Record<string,string>={UPGRADE:'套餐升级',RENEW:'续费',EXPANSION:'扩容'};
const statusType=(s:string)=>s==='APPROVED'?'success':['REJECTED','PAYMENT_FAILED'].includes(s)?'danger':s==='PAYMENT_CLOSED'?'info':'warning';
const orderAmount=computed(()=>orderType.value==='EXPANSION'?(targetAddon.value?.priceCents||0)*addonQuantity.value:billingCycle.value==='MONTHLY'?(targetPlan.value?.monthlyPriceCents||0):(targetPlan.value?.priceCents||0));
async function load(){loading.value=true;try{[plans.value,addons.value,summary.value,history.value]=await Promise.all([apiRequest<Plan[]>({url:'/api/subscriptions/plans',method:'GET'}),apiRequest<Addon[]>({url:'/api/subscriptions/addons',method:'GET'}),apiRequest<Summary>({url:'/api/subscriptions/current',method:'GET'}),apiRequest<Order[]>({url:'/api/subscriptions/upgrade-requests/mine',method:'GET'})])}finally{loading.value=false}}
function openOrder(type:'UPGRADE'|'RENEW'|'EXPANSION',value?:Plan|Addon){orderType.value=type;targetPlan.value=type==='RENEW'?summary.value?.plan:type==='UPGRADE'?value as Plan:undefined;targetAddon.value=type==='EXPANSION'?value as Addon:undefined;if(targetAddon.value?.pricePending)return ElMessage.info('扩展包价格待定，暂不开放购买');if(targetPlan.value?.quoteOnly||targetAddon.value?.quoteOnly)return contactSales();const cycles=targetPlan.value?.billingCycles||['YEARLY'];const current=(summary.value?.subscription?.billingCycle as 'MONTHLY'|'YEARLY')||'YEARLY';billingCycle.value=cycles.includes(current)?current:cycles[0];addonQuantity.value=1;voucher.value=undefined;paymentReference.value='';paidBy.value='';paymentMethod.value='ALIPAY';dialogVisible.value=true}
function contactSales(){ElMessage.info('该产品需要商务报价，请联系平台管理员或商务人员')}
function pick(event:Event){voucher.value=(event.target as HTMLInputElement).files?.[0]}
function submitCheckout(checkout:Checkout){const form=document.createElement('form');form.method=checkout.method;form.action=checkout.gateway;form.acceptCharset='UTF-8';form.enctype='application/x-www-form-urlencoded';form.style.display='none';Object.entries(checkout.fields).forEach(([name,value])=>{const input=document.createElement('input');input.type='hidden';input.name=name;input.value=value;form.appendChild(input)});document.body.appendChild(form);form.submit()}
function orderPayload(){return{orderType:orderType.value,billingCycle:billingCycle.value,...(targetPlan.value?{targetPlanId:targetPlan.value.id}:{}),...(targetAddon.value?{addonId:targetAddon.value.id,addonQuantity:addonQuantity.value}:{})}}
async function submit(){submitting.value=true;try{if(paymentMethod.value==='ALIPAY'){const result=await apiRequest<{order:Order;checkout:Checkout}>({url:'/api/subscriptions/orders/alipay',method:'POST',data:{...orderPayload(),paymentMethod:'ALIPAY'},timeout:30000});ElMessage.info('正在前往支付宝沙箱收银台');submitCheckout(result.checkout);return}if(orderAmount.value>0&&!voucher.value)return ElMessage.warning('请上传付款凭证');const data=new FormData();Object.entries(orderPayload()).forEach(([key,value])=>data.append(key,String(value)));data.append('paymentMethod','MANUAL');if(paymentReference.value)data.append('paymentReference',paymentReference.value);if(paidBy.value)data.append('paidBy',paidBy.value);if(voucher.value)data.append('voucher',voucher.value);await request.post('/api/subscriptions/orders',data,{headers:{'Content-Type':'multipart/form-data'},timeout:30000});ElMessage.success('订单已提交，请等待财务审核');dialogVisible.value=false;await load()}finally{submitting.value=false}}
async function continuePayment(order:Order){submitting.value=true;try{const result=await apiRequest<{order:Order;checkout:Checkout}>({url:`/api/subscriptions/orders/${order.id}/alipay/checkout`,method:'POST'});submitCheckout(result.checkout)}finally{submitting.value=false}}
async function checkPayment(orderId:string,announce=true){checkingPayment.value=true;try{const order=await apiRequest<Order>({url:`/api/subscriptions/orders/${orderId}/payment-status`,method:'GET',timeout:15000});if(order.status==='APPROVED')ElMessage.success('支付成功，套餐权益已自动开通');else if(announce)ElMessage.info(order.status==='PENDING_PAYMENT'?'暂未查询到付款结果，可完成支付后再次查询':statusText[order.status]||'支付状态已更新');await load()}finally{checkingPayment.value=false}}
const date=(v?:string)=>v?new Date(v).toLocaleDateString('zh-CN'):'-';
const retention=(p:Plan)=>p.historyRetentionMonths?`${p.historyRetentionMonths}个自然月`:`${p.historyRetentionDays||7}天`;
const resource=(v:string)=>({DEVICE:'设备',POINT:'点位',SCADA:'组态项目',USER:'用户',HISTORY:'个月历史保存'}[v]||v);
onMounted(async()=>{await load();const orderId=typeof route.query.alipayOrder==='string'?route.query.alipayOrder:'';if(orderId){await checkPayment(orderId).catch(()=>undefined);await router.replace({path:route.path,query:{}})}});
</script>

<template><div v-loading="loading"><div class="page-actions"><div><h1 class="page-title">版本与订阅</h1><p class="page-description">支持支付宝在线支付或线下凭证审核，支付完成后自动开通权益</p></div><el-button type="primary" :disabled="!!summary?.pendingOrder" @click="openOrder('RENEW')">续费当前版本</el-button></div>
<el-alert v-if="summary?.pendingOrder" type="warning" show-icon :closable="false" :title="summary.pendingOrder.status==='PENDING_PAYMENT'?`订单 ${summary.pendingOrder.orderNo} 等待支付宝付款`:`订单 ${summary.pendingOrder.orderNo} 正在财务审核中`" :description="summary.pendingOrder.status==='PENDING_PAYMENT'?`沙箱实付 ${money(summary.pendingOrder.paymentAmountCents||1)}；支付成功后权益自动生效。`:'审核完成前，当前订阅与额度保持不变。'"><template v-if="summary.pendingOrder.status==='PENDING_PAYMENT'" #default><div class="pending-actions"><span>沙箱实付 {{money(summary.pendingOrder.paymentAmountCents||1)}}；支付成功后权益自动生效。</span><el-button size="small" type="primary" plain :loading="submitting" @click="continuePayment(summary.pendingOrder)">继续支付</el-button><el-button size="small" :loading="checkingPayment" @click="checkPayment(summary.pendingOrder.id)">查询支付结果</el-button></div></template></el-alert>
<section class="current-card"><div><div class="status-row"><span>当前套餐</span><el-tag :type="summary?.subscription?.status==='ACTIVE'?'success':'warning'">{{subStatus[summary?.subscription?.status||'']||'未开通'}}</el-tag></div><h2>{{summary?.plan?.name||'未配置套餐'}}</h2><p>{{summary?.plan?.description||'请联系平台管理员配置套餐'}}</p><small>有效期：{{date(summary?.subscription?.startedAt)}} 至 {{date(summary?.subscription?.expiresAt)}} · 宽限至 {{date(summary?.subscription?.graceEndsAt)}}</small></div><div class="usage"><div v-for="item in [{label:'设备',data:summary?.usage.devices},{label:'点位',data:summary?.usage.points},{label:'组态项目',data:summary?.usage.scadaProjects},{label:'用户',data:summary?.usage.users}]" :key="item.label"><span>{{item.label}}</span><b>{{item.data?.used||0}} / {{quota(item.data?.limit||0)}}</b><el-progress :percentage="item.data?.limit ? Math.min(100,Math.round((item.data.used/item.data.limit)*100)) : 0" :show-text="false"/></div>
<div v-if="summary?.historyRetention" class="history-quota-card"><div class="history-quota-title"><span>历史保存时间</span><el-tooltip placement="top" effect="dark"><template #content><div class="history-quota-tooltip">按当前套餐及有效扩展权益计算保存期限；超出保存期限的数据设有7天清理宽限。已清理的数据无法恢复，升级套餐也不会恢复已清理数据。<template v-if="summary.historyRetention.addonMonths"><br/>扩展权益到期：{{date(summary.historyRetention.addonExpiresAt)}}，随对应订阅到期，不随续费自动延长。</template><template v-if="summary.historyRetention.graceEndsAt"><br/>当前清理宽限至：{{date(summary.historyRetention.graceEndsAt)}}。</template></div></template><button class="history-quota-help" aria-label="历史保存时间说明"><el-icon><QuestionFilled/></el-icon></button></el-tooltip></div><b>{{summary.historyRetention.label}}</b><span class="history-quota-note">可查询自 {{date(summary.historyRetention.queryEarliestAt)}} · 清理宽限期7天</span></div></div></section>

<h2 class="section-title">套餐升级</h2><div class="plan-grid"><article v-for="plan in availablePlans" :key="plan.id" class="plan-card"><span class="plan-code">{{plan.code}}</span><h3>{{plan.name}}</h3><p>{{plan.description||'暂无套餐说明'}}</p><strong>{{plan.quoteOnly?'商务报价':money(plan.priceCents)}}<small v-if="!plan.quoteOnly">/年</small></strong><ul><li>设备：{{quota(plan.deviceLimit)}}</li><li>云点位：{{quota(plan.pointLimit)}}</li><li>云组态：{{quota(plan.scadaProjectLimit)}}</li><li>用户：{{quota(plan.userLimit)}}</li><li>历史：{{retention(plan)}}</li></ul><el-button type="primary" plain :disabled="!!summary?.pendingOrder" @click="openOrder('UPGRADE',plan)">{{plan.quoteOnly?'联系商务':'申请升级'}}</el-button></article><el-empty v-if="!availablePlans.length" description="暂无其他可申请套餐"/></div>

<h2 class="section-title">按需扩容</h2><div class="addon-grid"><article v-for="addon in addons" :key="addon.id"><div><b>{{addon.name}}</b><span>{{addon.description||`${resource(addon.resourceType)}额度 +${addon.quantity}`}}</span></div><strong>+{{addon.quantity.toLocaleString()}} {{resource(addon.resourceType)}}</strong><em>{{addon.pricePending?'价格待定':addon.quoteOnly?'商务报价':`${money(addon.priceCents)} / ${addon.resourceType==='HISTORY'?'份，随订阅到期':'年'}`}}</em><el-button type="primary" plain :disabled="!!summary?.pendingOrder||addon.pricePending||summary?.subscription?.status==='EXPIRED'" @click="openOrder('EXPANSION',addon)">{{addon.quoteOnly?'联系商务':'购买扩容'}}</el-button></article></div>

<h2 class="section-title">订单记录</h2><section class="table-panel"><el-table :data="history" empty-text="暂无订单"><el-table-column prop="orderNo" label="订单号" min-width="190"/><el-table-column label="类型" width="110"><template #default="{row}"><el-tag effect="plain">{{typeText[row.orderType]}}</el-tag></template></el-table-column><el-table-column label="订单内容" min-width="180"><template #default="{row}">{{row.targetPlan?.name||row.addon?.name||'-'}}<span v-if="row.orderType==='EXPANSION'"> × {{row.addonQuantity}}</span></template></el-table-column><el-table-column label="金额" width="150"><template #default="{row}"><div>{{money(row.amountCents)}}</div><small v-if="row.paymentMethod==='ALIPAY'&&row.paymentAmountCents!==row.amountCents" class="sandbox-amount">沙箱实付 {{money(row.paymentAmountCents||1)}}</small></template></el-table-column><el-table-column label="支付方式" width="120"><template #default="{row}">{{row.paymentMethod==='ALIPAY'?'支付宝':'线下凭证'}}</template></el-table-column><el-table-column label="提交时间" min-width="180"><template #default="{row}">{{new Date(row.requestedAt).toLocaleString('zh-CN',{hour12:false})}}</template></el-table-column><el-table-column label="状态" width="130"><template #default="{row}"><el-tag :type="statusType(row.status)">{{statusText[row.status]||row.status}}</el-tag></template></el-table-column><el-table-column label="说明" min-width="180"><template #default="{row}"><el-button v-if="row.status==='PENDING_PAYMENT'" link type="primary" @click="continuePayment(row)">继续支付</el-button><span v-else>{{row.financeReviews?.[0]?.note||'-'}}</span></template></el-table-column></el-table></section>

<el-dialog v-model="dialogVisible" :title="typeText[orderType]" width="600px"><el-alert v-if="targetAddon?.resourceType==='HISTORY'" type="info" :closable="false" :description="`每份延长3个自然月，随当前订阅于${date(summary?.subscription?.expiresAt)}到期；不随套餐续费自动延长，不恢复已清理的数据。`"/><div class="apply-summary"><span>订单内容</span><b>{{targetPlan?.name||targetAddon?.name}}</b><template v-if="orderType!=='EXPANSION'"><span>订阅周期</span><el-radio-group v-model="billingCycle"><el-radio-button v-if="targetPlan?.billingCycles.includes('MONTHLY')" value="MONTHLY">月付</el-radio-button><el-radio-button v-if="targetPlan?.billingCycles.includes('YEARLY')" value="YEARLY">年付</el-radio-button></el-radio-group></template><template v-else><span>购买数量</span><el-input-number v-model="addonQuantity" :min="1" :max="100"/></template><span>订单金额</span><strong>{{money(orderAmount)}}</strong></div><div class="payment-choice"><b>支付方式</b><el-radio-group v-model="paymentMethod"><el-radio-button value="ALIPAY">支付宝沙箱</el-radio-button><el-radio-button value="MANUAL">线下付款</el-radio-button></el-radio-group></div><template v-if="paymentMethod==='ALIPAY'"><el-alert type="warning" :closable="false" show-icon title="沙箱测试环境：本次实际支付 0.01 元" description="将进入支付宝沙箱收银台；支付成功后系统自动查询结果并开通权益，不进入财务审核。"/></template><template v-else><el-alert type="info" :closable="false" title="请完成线下付款后上传凭证；财务审核通过后权益自动生效。"/><div class="payment-fields"><el-input v-model="paidBy" placeholder="付款人（可选）"/><el-input v-model="paymentReference" placeholder="付款流水号（可选）"/></div><label class="upload-box"><input type="file" accept="image/jpeg,image/png,image/webp,application/pdf" hidden @change="pick"/><el-icon><UploadFilled/></el-icon><b>{{voucher?.name||(orderAmount===0?'零元订单可不上传凭证':'点击选择付款凭证')}}</b><span>支持 JPG、PNG、WebP 或 PDF，最大 8 MB</span></label></template><template #footer><el-button @click="dialogVisible=false">取消</el-button><el-button type="primary" :loading="submitting" @click="submit">{{paymentMethod==='ALIPAY'?'前往支付宝支付 0.01 元':'提交财务审核'}}</el-button></template></el-dialog></div></template>

<style scoped>
.usage>.history-quota-card{grid-column:1 / -1}.history-quota-title{display:flex;align-items:center;gap:7px}.history-quota-help{display:inline-flex;align-items:center;justify-content:center;width:20px;height:20px;padding:0;border:0;border-radius:4px;background:transparent;color:#94a3b8;cursor:help}.history-quota-help:hover,.history-quota-help:focus-visible{color:#409eff;outline:1px solid currentColor}.history-quota-note{line-height:1.6}.history-quota-tooltip{max-width:300px;line-height:1.7}
.pending-actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.sandbox-amount{color:#d97706}.current-card{display:grid;grid-template-columns:minmax(260px,.75fr) 1.5fr;gap:28px;margin:18px 0 26px;padding:26px;border:1px solid #dce6f3;border-radius:15px;background:linear-gradient(135deg,#fff,#f5f9ff)}.status-row{display:flex;align-items:center;gap:10px}.current-card>div>span,.usage span{color:#7f8da2;font-size:13px}.current-card h2{margin:7px 0;color:#172b4d;font-size:28px}.current-card p{color:#76869d}.current-card small{color:#8090a6}.usage{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.usage>div{display:grid;gap:9px;padding:16px;border-radius:12px;background:#fff}.usage b{font-size:18px;color:#233b5c}.section-title{margin:28px 0 14px;font-size:18px}.plan-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.plan-card{display:grid;gap:10px;padding:20px;border:1px solid #e0e8f2;border-radius:13px;background:#fff}.plan-code{color:#4285ec;font-size:11px}.plan-card h3{margin:0;font-size:19px}.plan-card p{min-height:38px;margin:0;color:#7f8da2;font-size:13px}.plan-card strong{color:#1769e0;font-size:25px}.plan-card strong small{font-size:12px}.plan-card ul{display:grid;grid-template-columns:1fr 1fr;gap:7px;margin:5px 0 8px;padding:13px 13px 13px 28px;border-radius:9px;background:#f7f9fc;color:#51647e;font-size:13px}.addon-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.addon-grid article{display:grid;grid-template-columns:1fr auto;align-items:center;gap:8px 16px;padding:18px;border:1px solid #e0e8f2;border-radius:12px;background:#fff}.addon-grid article>div{display:grid;gap:5px}.addon-grid span{color:#8090a6;font-size:12px}.addon-grid strong{color:#215181}.addon-grid em{color:#1769e0;font-style:normal}.apply-summary{display:grid;grid-template-columns:130px 1fr;align-items:center;gap:12px;margin-bottom:18px;padding:16px;border-radius:10px;background:#f6f9fd}.apply-summary strong{color:#1769e0;font-size:22px}.payment-choice{display:flex;align-items:center;justify-content:space-between;gap:16px;margin:0 0 15px}.payment-fields{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:15px}.upload-box{display:grid;place-items:center;gap:8px;margin-top:15px;padding:22px;border:1px dashed #9dbce8;border-radius:12px;color:#52739d;cursor:pointer;background:#f8fbff}.upload-box .el-icon{font-size:28px;color:#3b82f6}.upload-box span{font-size:12px;color:#8a98aa}@media(max-width:900px){.current-card{grid-template-columns:1fr}.plan-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:650px){.usage,.plan-grid,.addon-grid,.payment-fields{grid-template-columns:1fr}}
</style>
